const BUILD_VERSION="3.9.0";
const KEY="nexaro-crm-v2-0";
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??"").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;");
const uid=()=>crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
const today=()=>new Date().toISOString().slice(0,10);
const money=n=>new Intl.NumberFormat("de-DE",{style:"currency",currency:"EUR"}).format(Number(n)||0);
const addressText=(street,zip,city)=>[street,zip,city].filter(Boolean).join(", ");
function splitAddress(a){const raw=String(a||"").trim();const m=raw.match(/^(.*?)(?:,|\s)\s*(\d{5})\s+(.+)$/);return m?{street:m[1].trim().replace(/,$/,""),zip:m[2],city:m[3].trim()}:{street:raw,zip:"",city:""}}
function normalizeAddresses(){for(const l of S.leads){if(!l.zip||!l.city){const x=splitAddress(l.address);l.street=l.street||x.street;l.zip=l.zip||x.zip;l.city=l.city||x.city}l.address=addressText(l.street,l.zip,l.city)||l.address||""}for(const c of S.customers){if(!c.zip||!c.city){const x=splitAddress(c.address);c.street=c.street||x.street;c.zip=c.zip||x.zip;c.city=c.city||x.city}c.address=addressText(c.street,c.zip,c.city)||c.address||""}}
const base={leads:[],customers:[],tasks:[],visits:[],quotes:[],invoices:[],quoteSequence:0,customerSequence:0,routePlans:[],settings:{company:"neXaro Solutions"}};
let S=(()=>{try{
const legacy=localStorage.getItem(KEY)||localStorage.getItem("nexaro-crm-v1-2")||localStorage.getItem("nexaro-crm-v1-3")||"{}";
const x=JSON.parse(legacy);return {...base,...x,leads:x.leads||[],customers:x.customers||[],tasks:x.tasks||[],visits:x.visits||[],quotes:x.quotes||[],invoices:x.invoices||[],settings:x.settings||{}}}catch{return structuredClone(base)}})();
S.customers=Array.isArray(S.customers)?S.customers:[];
S.customerSequence=Number(S.customerSequence)||0;
S.routePlans=Array.isArray(S.routePlans)?S.routePlans:[];
S.visits=Array.isArray(S.visits)?S.visits:[];
function nextCustomerNo(){S.customerSequence=(S.customerSequence||0)+1;return `KD-${String(S.customerSequence).padStart(4,'0')}`}
function customerFromLead(l){return {id:uid(),customerNo:l.customerNo||nextCustomerNo(),company:l.company||"",contact:l.contact||"",phone:l.phone||"",email:l.email||"",address:l.address||"",street:l.street||"",zip:l.zip||"",city:l.city||"",vatId:l.vatId||"",territory:l.territory||"",priority:l.priority||"Mittel",notes:l.notes||"",sourceLeadId:l.id||null,updatedAt:new Date().toISOString()}}
function normalizeCompany(v){return String(v||'').trim().toLowerCase().replace(/\s+/g,' ')}
function findMatchingCustomer(data){const company=normalizeCompany(data.company),email=String(data.email||'').trim().toLowerCase();return S.customers.find(c=>data.customerId&&c.id===data.customerId)||S.customers.find(c=>c.sourceLeadId&&data.sourceLeadId&&c.sourceLeadId===data.sourceLeadId)||S.customers.find(c=>company&&normalizeCompany(c.company)===company&&(email?String(c.email||'').trim().toLowerCase()===email:true))||null}
function ensureCustomerForLead(leadId){if(!leadId)return null;const l=S.leads.find(x=>x.id===leadId);if(!l)return null;let c=findMatchingCustomer({customerId:l.customerId,sourceLeadId:leadId,company:l.company,email:l.email});if(!c){c=customerFromLead(l);S.customers.unshift(c)}else{c={...c,company:l.company||c.company,contact:l.contact||c.contact,phone:l.phone||c.phone,email:l.email||c.email,address:l.address||c.address,street:l.street||c.street||"",zip:l.zip||c.zip||"",city:l.city||c.city||"",vatId:l.vatId||c.vatId,customerNo:l.customerNo||c.customerNo||nextCustomerNo(),notes:l.notes||c.notes,sourceLeadId:c.sourceLeadId||leadId,updatedAt:new Date().toISOString()};const i=S.customers.findIndex(x=>x.id===c.id);if(i>=0)S.customers[i]=c}l.customerId=c.id;return c}
function customerById(id){return S.customers.find(c=>c.id===id)||null}
function syncCustomer(c,fields={}){if(!c)return null;Object.assign(c,{company:fields.company??c.company,contact:fields.contact??c.contact,phone:fields.phone??c.phone,email:fields.email??c.email,address:fields.address??c.address,street:fields.street??c.street??"",zip:fields.zip??c.zip??"",city:fields.city??c.city??"",vatId:fields.vatId??c.vatId,customerNo:fields.customerNo||c.customerNo||nextCustomerNo(),territory:fields.territory??(c.territory||""),priority:fields.priority??(c.priority||"Mittel"),notes:fields.notes??c.notes,updatedAt:new Date().toISOString()});return c}
function migrateCustomers(){for(const l of S.leads){if(l.customerId&&customerById(l.customerId))continue;const c=ensureCustomerForLead(l.id);if(c)l.customerId=c.id}for(const c of S.customers){if(!c.customerNo)c.customerNo=nextCustomerNo();if(!c.priority)c.priority="Mittel"}}
S.quotes=(S.quotes||[]).map(q=>({...q,items:q.items||[{description:q.product||"",qty:q.qty||1,unit:q.unit||"Stück",price:q.price||0}]}));
S.vapeCart=Array.isArray(S.vapeCart)?S.vapeCart:[];
let lf="all",tf="open",area=null,route=[];
const save=()=>localStorage.setItem(KEY,JSON.stringify(S));
normalizeAddresses();migrateCustomers();save();
const toast=m=>{const t=$("#toast");t.textContent=m;t.classList.add("show");setTimeout(()=>t.classList.remove("show"),1900)};
const close=id=>$("#"+id)?.close(), open=id=>$("#"+id)?.showModal();
function qual(t){t=+t||0;return t>=15000?{l:"A",x:"Sehr starkes Potenzial",c:"qual-A"}:t>=10000?{l:"B",x:"Stark qualifiziert",c:"qual-B"}:t>=5000?{l:"C",x:"Qualifiziert",c:"qual-C"}:{l:"D",x:"Unter internem Vertriebsziel",c:"qual-D"}}
const sl=s=>({neu:"Neu",kontaktiert:"Kontaktiert",termin:"Termin",angebot:"Angebot",gewonnen:"Gewonnen",verloren:"Verloren"}[s]||s);
function nav(id){$$('.screen').forEach(x=>x.classList.toggle('active',x.id===id));$$('#nav button').forEach(x=>x.classList.toggle('active',x.dataset.screen===id));window.scrollTo(0,0);render()}
$$('[data-screen]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();nav(b.dataset.screen)}));
document.onclick=e=>{const c=e.target.closest('[data-close]');if(c){close(c.dataset.close);return}const a=e.target.closest('[data-action]')?.dataset.action;if(a)act(a)};
function act(a){if(a==='new-lead')return lead();if(a==='new-task')return task();if(a==='pricing')return pricing();if(a==='commission')return commission();if(a==='new-quote')return quote();if(a==='export-csv')return csv();if(a==='backup')return download('nexaro-crm-backup.json',JSON.stringify(S,null,2),'application/json');if(a==='restore')return $('#restoreInput').click();if(a==='demo')return demo();if(a==='clear'&&confirm('Alle lokalen CRM-Daten löschen?')){S=structuredClone(base);save();render();toast('CRM gelöscht')}}
function lead(id=null){$('#leadForm').reset();$('#leadId').value=id||'';$('#leadDialogTitle').textContent=id?'SUMUP-Lead bearbeiten':'Neuer SUMUP-Lead';$('#fCustomer').innerHTML=customerOptions();const l=id&&S.leads.find(x=>x.id===id);if(l){for(const [k,i] of Object.entries({company:'fCompany',industry:'fIndustry',status:'fStatus',contact:'fContact',phone:'fPhone',email:'fEmail',street:'fStreet',zip:'fZip',city:'fCity',tpv:'fTpv',provider:'fProvider',terminal:'fTerminal',product:'fProduct',priority:'fPriority',need:'fNeed',next:'fNext',due:'fDue',notes:'fNotes'}))$('#'+i).value=l[k]??'';if(l.customerId){$('#fCustomer').value=l.customerId}else{const c=ensureCustomerForLead(l.id);$('#fCustomer').value=c?.id||''}}else{$('#fDue').value=today();$('#fPriority').value='Hoch';$('#fStatus').value='neu'}hint();open('leadDialog')}
function hint(){const q=qual($('#fTpv').value);$('#qualificationHint').className='qual-box '+q.c;$('#qualificationHint').innerHTML='<b>Interne Qualifizierung: '+q.l+'</b><br>'+q.x+'. '+(+$('#fTpv').value>=5000?'Internes Vertriebsziel erreicht.':'Unter €5.000 TPV: intern niedriger priorisieren.')}$('#fTpv').oninput=hint;
$('#leadForm').onsubmit=e=>{e.preventDefault();const company=$('#fCompany').value.trim();if(!company)return toast('Firma fehlt');const tpv=+$('#fTpv').value||0,q=qual(tpv),id=$('#leadId').value||uid(),d={id,company,industry:$('#fIndustry').value,status:$('#fStatus').value,contact:$('#fContact').value.trim(),phone:$('#fPhone').value.trim(),email:$('#fEmail').value.trim(),street:$('#fStreet').value.trim(),zip:$('#fZip').value.trim(),city:$('#fCity').value.trim(),address:addressText($('#fStreet').value.trim(),$('#fZip').value.trim(),$('#fCity').value.trim()),tpv,qualification:q.l,qualified:tpv>=5000,provider:$('#fProvider').value.trim(),terminal:$('#fTerminal').value.trim(),product:$('#fProduct').value,priority:$('#fPriority').value,need:$('#fNeed').value.trim(),next:$('#fNext').value.trim(),due:$('#fDue').value,notes:$('#fNotes').value.trim(),updatedAt:new Date().toISOString()};const i=S.leads.findIndex(x=>x.id===id);i>=0?S.leads[i]={...S.leads[i],...d}:S.leads.unshift(d);let c=customerById($('#fCustomer').value);if(!c)c=findMatchingCustomer({company,email:d.email});if(!c)c=customerFromLead({...d,id:d.id});syncCustomer(c,d);if(!S.customers.some(x=>x.id===c.id))S.customers.unshift(c);d.customerId=c.id;const li=S.leads.findIndex(x=>x.id===id);if(li>=0)S.leads[li].customerId=c.id;save();close('leadDialog');render();toast('Lead gespeichert · Kundenakte verknüpft')};
$('#fCustomer')?.addEventListener('change',()=>{const c=customerById($('#fCustomer').value);if(!c)return;$('#fCompany').value=c.company||'';$('#fContact').value=c.contact||'';$('#fPhone').value=c.phone||'';$('#fEmail').value=c.email||'';$('#fStreet').value=c.street||splitAddress(c.address).street||'';$('#fZip').value=c.zip||splitAddress(c.address).zip||'';$('#fCity').value=c.city||splitAddress(c.address).city||'';$('#fVatId')?.value&&(null)});
function card(l){const q=qual(l.tpv);return `<article class="card lead-card"><div class="row"><div><h3>${esc(l.company)}</h3><div class="meta">${esc(l.industry||'')} · ${esc(l.address||'Keine Adresse')}</div>${l.contact?`<div class="meta">👤 ${esc(l.contact)}${l.phone?' · '+esc(l.phone):''}</div>`:''}</div><span class="badge">${esc(sl(l.status))}</span></div><div class="chips"><span class="chip ${q.l==='A'||q.l==='B'?'good':q.l==='C'?'warn':'bad'}">TPV ${money(l.tpv)} · ${q.l}</span><span class="chip">${esc(l.priority||'Mittel')} Priorität</span>${l.product?`<span class="chip">${esc(l.product)}</span>`:''}</div>${l.next||l.due?`<div class="meta" style="margin-top:9px">↗ ${esc(l.next||'Follow-up')} · ${esc(l.due||'')}</div>`:''}<div class="lead-actions">${l.phone?`<button data-phone="${esc(l.phone)}">☎️ Anrufen</button>`:''}${l.address?`<button data-map="${encodeURIComponent(l.address)}">🧭 Maps</button>`:''}<button data-edit="${l.id}">✏️ Bearbeiten</button><button data-visit="${l.id}">📝 Besuch</button><button data-guide="${l.id}">🎯 Leitfaden</button><button data-quote="${l.id}">💼 Angebot</button><button data-del="${l.id}">🗑️</button></div></article>`}
let guideState={step:0,answers:{},leadId:"",data:{}};
const GUIDE_STEPS=[
 {eyebrow:'01 · EINSTIEG',title:'Gespräch eröffnen',text:'„Ich bin heute kurz bei Ihnen, weil wir uns anschauen können, ob Sie bei Kartenzahlungen aktuell zu viel bezahlen oder unnötig kompliziert arbeiten.“',choices:[['permission','Gespräch passt gerade','Gespräch starten'],['later','Gerade ungünstig','Termin vereinbaren']]},
 {eyebrow:'02 · BEDARF',title:'Was ist dem Kunden am wichtigsten?',text:'Nicht alles gleichzeitig verkaufen. Erst den wichtigsten Bedarf identifizieren.',choices:[['kosten','Kosten & Transparenz','Kosten'],['einfachheit','Einfachheit & Bedienung','Einfachheit'],['geschwindigkeit','Schnelligkeit','Geschwindigkeit'],['kasse','Kasse / POS / Gesamtprozess','Kasse / POS']]},
 {eyebrow:'03 · STATUS QUO',title:'Aktuelle Situation festhalten',text:'Jetzt den Ist-Zustand konkret machen. Die Antworten werden direkt am SUMUP-Lead gespeichert.',choices:[['anbieter','Anbieter + aktuelle Lösung klären','Anbieter'],['volumen','Kartenzahlungsvolumen klären','TPV'],['problem','Größtes Problem klären','Problem']]},
 {eyebrow:'04 · EINWAND',title:'Einwand → Rückfrage → Lösung',text:'Wenn ein Einwand kommt, nicht sofort argumentieren. Erst verstehen, dann passend reagieren.',choices:[['zufrieden','„Ich bin zufrieden.“','Zufriedenheit'],['aufwand','„Zu viel Aufwand.“','Aufwand'],['gebuehren','„Gebühren sind egal.“','Gebühren'],['denken','„Ich möchte darüber nachdenken.“','Bedenkzeit'],['kein','Kein Einwand','Kein Einwand']]},
 {eyebrow:'05 · NÄCHSTER SCHRITT',title:'Konkrete Aktion vereinbaren',text:'Das Gespräch endet immer mit einer klaren nächsten Aktion.',choices:[['vergleich','Tarifvergleich durchführen','Tarifvergleich'],['angebot','Angebot vorbereiten','Angebot'],['termin','Folgetermin vereinbaren','Termin'],['followup','Wiedervorlage setzen','Follow-up'],['keininteresse','Kein Interesse','Kein Interesse']]},
 {eyebrow:'06 · DOKUMENTATION',title:'Gespräch abschließen',text:'Kurze Dokumentation speichern. Danach bleibt der Lead im passenden SUMUP-Status.',choices:[['save','Gespräch speichern','Speichern']]}
];
const GUIDE_TEXT={
 kosten:{q:'Was ist für Sie heute die größte Kostenposition bei Kartenzahlungen?',a:'Kosten konkret machen und anschließend mit den bekannten Daten in den Tarifvergleich gehen.'},
 einfachheit:{q:'Was soll beim täglichen Bezahlen für Ihr Team möglichst einfach funktionieren?',a:'Den wichtigsten Arbeitsschritt identifizieren und nur die dafür relevante Lösung zeigen.'},
 geschwindigkeit:{q:'Wo verlieren Sie heute Zeit – beim Bezahlen, bei der Bedienung oder im Ablauf danach?',a:'Den konkreten Engpass herausarbeiten und die passende Lösung darauf beziehen.'},
 kasse:{q:'Wie laufen Kasse, Kartenzahlung und Tagesabschluss heute zusammen?',a:'Gesamtprozess verstehen, bevor eine konkrete Lösung empfohlen wird.'},
 anbieter:{q:'Welchen Anbieter und welches Terminal nutzen Sie aktuell?',a:'Anbieter und bestehende Lösung dokumentieren; danach Kosten und Bedarf vergleichen.'},
 volumen:{q:'Wie hoch ist Ihr monatliches Kartenzahlungsvolumen ungefähr?',a:'TPV im Lead erfassen und anschließend die passende Vergleichsrechnung öffnen.'},
 problem:{q:'Was stört Sie an Ihrer aktuellen Lösung am meisten?',a:'Das Problem in einem Satz festhalten und die Argumentation genau darauf ausrichten.'}
};
const GUIDE_OBJECTIONS={
 zufrieden:{q:'Was funktioniert für Sie heute besonders gut – und was würden Sie trotzdem gern verbessern?',a:'Nicht gegen Zufriedenheit argumentieren. Erst den Status quo verstehen, dann nur den relevanten Mehrwert zeigen.'},
 aufwand:{q:'Wenn wir den Aufwand so gering wie möglich halten: Was müsste für Sie erledigt sein, damit ein Wechsel interessant wird?',a:'Aufwand konkretisieren und den nächsten kleinen Schritt anbieten – Vergleich, Angebot oder Termin.'},
 gebuehren:{q:'Wenn Gebühren nicht der Hauptpunkt sind: Worauf kommt es Ihnen bei der täglichen Nutzung am meisten an?',a:'Nicht künstlich auf Preis fokussieren. Relevante Anforderungen des Kunden herausarbeiten.'},
 denken:{q:'Klar. Was möchten Sie vor der Entscheidung noch prüfen?',a:'Den offenen Punkt identifizieren und einen konkreten Follow-up-Termin vereinbaren.'}
};
function guideChoiceHtml(step){const base=GUIDE_STEPS[step];const need=guideState.answers[1];let s=step===2&&need?{...base,text:(GUIDE_TEXT[need]?.q||base.text)+' Danach den Ist-Zustand festhalten.',title:'Status passend zum Bedarf klären'}:base;if(step===1&&guideState.answers[0]==='later')s={eyebrow:'02 · FOLLOW-UP',title:'Konkreten Rückruf vereinbaren',text:'Wenn es gerade ungünstig ist, nicht verkaufen. Einen verbindlichen nächsten Kontakt vereinbaren.',choices:[['callback','Rückruftermin vereinbaren','Rückruf'],['visit','Vor-Ort-Termin vereinbaren','Termin'],['followup','Wiedervorlage setzen','Follow-up']]};if(step===4&&guideState.answers[0]==='later')s={eyebrow:'05 · NÄCHSTER SCHRITT',title:'Rückruf verbindlich machen',text:'Ein konkreter Termin ist besser als „Ich melde mich irgendwann“.',choices:[['termin','Folgetermin vereinbaren','Termin'],['followup','Wiedervorlage setzen','Follow-up']]};return `<div class="card guide-current"><div class="eyebrow">${s.eyebrow}</div><h3>${s.title}</h3><p>${s.text}</p><div class="guide-choice-grid">${s.choices.map(([k,label,short])=>`<button type="button" class="secondary guide-choice ${guideState.answers[step]===k?'selected':''}" data-guide-choice="${k}">${label}</button>`).join('')}</div><div id="guideDynamic" class="result-stack" style="margin-top:12px"></div></div>`}
function renderGuideStep(){const step=guideState.step;$('#guideProgress').textContent=`Schritt ${step+1} von ${GUIDE_STEPS.length}`;$('#guideWizard').innerHTML=guideChoiceHtml(step);$('#guideBack').disabled=step===0;$('#guideNext').textContent=step===GUIDE_STEPS.length-1?'Speichern ✓':'Weiter →';const choice=guideState.answers[step];if(choice)renderGuideDynamic(choice);}
function renderGuideDynamic(choice){const el=$('#guideDynamic');if(!el)return;if(guideState.step===2){const x=GUIDE_TEXT[choice];if(x){const d=guideState.data;const existing=choice==='anbieter'?d.provider||'':choice==='volumen'?d.tpv||'':choice==='problem'?d.problem||'':'';const label=choice==='anbieter'?'Aktueller Anbieter':choice==='volumen'?'Monatliches Kartenzahlungsvolumen (€)':'Größtes Problem';const type=choice==='volumen'?'number':'text';el.innerHTML=`<div class="result"><b>Nächste Frage</b><strong>${esc(x.q)}</strong></div><label class="guide-input">${label}<input id="guideAnswerInput" type="${type}" value="${esc(existing)}" placeholder="${choice==='volumen'?'z. B. 5000':'Antwort des Kunden'}"></label><div class="result"><b>Vorgehen</b><small>${esc(x.a)}</small></div>`;return}}if(GUIDE_TEXT[choice]){const x=GUIDE_TEXT[choice];el.innerHTML=`<div class="result"><b>Nächste Frage</b><strong>${esc(x.q)}</strong></div><div class="result"><b>Vorgehen</b><small>${esc(x.a)}</small></div>`;return}if(GUIDE_OBJECTIONS[choice]){const x=GUIDE_OBJECTIONS[choice];el.innerHTML=`<div class="result"><b>Rückfrage</b><strong>${esc(x.q)}</strong></div><div class="result"><b>Vorgehen</b><small>${esc(x.a)}</small></div>`;return}const map={permission:['Ziel','Gespräch starten und Bedarf klären.'],later:['Nächster Schritt','Gespräch nicht erzwingen – konkreten nächsten Kontakt vereinbaren.'],callback:['Aktion','Rückruftermin konkret festlegen.'],visit:['Aktion','Vor-Ort-Termin konkret festlegen.'],vergleich:['Aktion','Tarifvergleich mit den erfassten Daten öffnen.'],angebot:['Aktion','SUMUP-Angebot vorbereiten.'],termin:['Aktion','Konkreten Folgetermin vereinbaren.'],followup:['Aktion','Wiedervorlage mit Datum setzen.'],keininteresse:['Aktion','Kein Interesse dokumentieren und respektvoll abschließen.'],kein:['Hinweis','Kein Einwand – weiter zur Bedarfsermittlung oder zum Abschluss.']};const x=map[choice];if(x){el.innerHTML=`<div class="result"><b>${x[0]}</b><strong>${x[1]}</strong></div>`;if(choice==='vergleich')el.insertAdjacentHTML('beforeend','<button type="button" class="primary" id="guidePricing" style="margin-top:10px">🧮 Tarifvergleich öffnen</button>');if(['callback','visit','termin','followup'].includes(choice))el.insertAdjacentHTML('beforeend','<label class="guide-input">Datum für den nächsten Kontakt<input id="guideFollowupDate" type="date" value="${esc(guideState.data.followupDate||today())}"></label>')}}
function openGuide(id){const l=S.leads.find(x=>x.id===id);if(!l)return;guideState={step:0,answers:{...(l.guideAnswers||{})},leadId:id,data:{...(l.guideData||{}),provider:l.guideData?.provider||l.provider||'',tpv:l.guideData?.tpv||l.tpv||'',problem:l.guideData?.problem||l.need||'',followupDate:l.guideData?.followupDate||l.due||today()}};$('#guideLeadId').value=id;$('#guideLeadMeta').innerHTML=`<b>${esc(l.company)}</b><div class="meta">${esc(l.address||'Keine Adresse')} · ${esc(l.contact||'Kein Ansprechpartner')}</div><div class="chips"><span class="chip">TPV ${money(l.tpv)}</span><span class="chip">${esc(l.priority||'Mittel')} Priorität</span>${l.provider?`<span class="chip">Aktuell: ${esc(l.provider)}</span>`:''}</div>`;renderGuideStep();open('guideDialog')}
function saveGuideConversation(){const id=guideState.leadId,l=S.leads.find(x=>x.id===id);if(!l)return;const a=guideState.answers;const d=guideState.data||{};const notes=[];if(a[1])notes.push('Bedarf: '+(GUIDE_STEPS[1].choices.find(x=>x[0]===a[1])?.[2]||a[1]));if(a[2])notes.push('Status: '+(GUIDE_STEPS[2].choices.find(x=>x[0]===a[2])?.[2]||a[2]));if(d.provider)notes.push('Anbieter: '+d.provider);if(d.tpv)notes.push('TPV im Gespräch: '+money(+d.tpv||0));if(d.problem)notes.push('Problem: '+d.problem);if(a[3])notes.push('Einwand: '+(GUIDE_STEPS[3].choices.find(x=>x[0]===a[3])?.[2]||a[3]));const next=a[4];l.guideAnswers=a;l.guideData=d;l.conversationResult=next==='angebot'?'Angebot gewünscht':next==='vergleich'?'Tarifvergleich durchgeführt':next==='termin'?'Termin vereinbaren':next==='followup'?'Wiedervorlage gesetzt':next==='keininteresse'?'Kein Interesse':a[0]==='later'?'Rückruf vereinbaren':'Gespräch dokumentiert';l.conversationNote=notes.join(' · ');l.conversationUpdatedAt=new Date().toISOString();if(d.provider)l.provider=d.provider;if(d.tpv!==''&&d.tpv!=null){l.tpv=+d.tpv||0;l.qualification=qual(l.tpv).l;l.qualified=l.tpv>=5000}if(d.problem)l.need=d.problem;if(d.followupDate){l.due=d.followupDate}if(next==='angebot'&&l.status!=='gewonnen')l.status='angebot';if(next==='keininteresse')l.status='verloren';if(next==='termin'||next==='callback'||next==='visit')l.status='termin';if(next==='vergleich'&&l.status==='neu')l.status='kontaktiert';if((next==='followup'||next==='callback'||next==='visit'||next==='termin'||a[0]==='later')&&d.followupDate){S.tasks.unshift({id:uid(),title:'SUMUP Follow-up · '+l.company,due:d.followupDate,leadId:l.id,customerId:l.customerId||'',note:l.conversationResult||'Nach Gespräch',done:false})}save();close('guideDialog');render();toast('Gespräch dokumentiert · Daten und nächster Schritt gespeichert')}
$('#guideDialog')?.addEventListener('click',e=>{const b=e.target.closest('[data-guide-choice]');if(b){const step=guideState.step;guideState.answers[step]=b.dataset.guideChoice;if(step===2){const v=$('#guideAnswerInput')?.value?.trim()||'';if(b.dataset.guideChoice==='anbieter')guideState.data.provider=v;if(b.dataset.guideChoice==='volumen')guideState.data.tpv=v;if(b.dataset.guideChoice==='problem')guideState.data.problem=v}renderGuideStep();return}if(e.target.closest('#guideBack')){if(guideState.step>0){guideState.step--;renderGuideStep()}return}if(e.target.closest('#guidePricing')){close('guideDialog');pricing();return}if(e.target.closest('#guideNext')){const step=guideState.step;if(step===2){const v=$('#guideAnswerInput')?.value?.trim()||'';const c=guideState.answers[2];if(!c||!v)return toast('Bitte die Gesprächsantwort erfassen');if(c==='anbieter')guideState.data.provider=v;if(c==='volumen')guideState.data.tpv=v;if(c==='problem')guideState.data.problem=v}if(step===4){const v=$('#guideFollowupDate')?.value||'';if(['callback','visit','termin','followup'].includes(guideState.answers[4])&&!v)return toast('Bitte Datum für den nächsten Kontakt wählen');if(v)guideState.data.followupDate=v}if(guideState.step===GUIDE_STEPS.length-1)return saveGuideConversation();if(!guideState.answers[guideState.step])return toast('Bitte eine Auswahl treffen');guideState.step++;renderGuideStep();return}if(e.target.closest('#guideWizard')&&e.target.closest('.guide-copy')){return}});

