const weatherText={0:'Klarer Himmel',1:'Überwiegend klar',2:'Teilweise bewölkt',3:'Bedeckt',45:'Nebel',48:'Reifnebel',51:'Leichter Nieselregen',53:'Nieselregen',55:'Starker Nieselregen',61:'Leichter Regen',63:'Regen',65:'Starker Regen',71:'Leichter Schneefall',73:'Schneefall',75:'Starker Schneefall',80:'Regenschauer',81:'Regenschauer',82:'Starke Regenschauer',95:'Gewitter',96:'Gewitter mit Hagel',99:'Starkes Gewitter mit Hagel'};
function weatherIcon(c){return c===0?'☀️':([1,2].includes(c)?'🌤️':([3].includes(c)?'☁️':([45,48].includes(c)?'🌫️':([51,53,55,61,63,65,80,81,82].includes(c)?'🌧️':([71,73,75].includes(c)?'🌨️':'⛈️')))))}
async function loadWeather(){
 const btn=$('#loadWeather'); if(!btn)return; btn.disabled=true; btn.textContent='📍 Standort wird ermittelt …';
 try{
  const pos=await new Promise((res,rej)=>navigator.geolocation?navigator.geolocation.getCurrentPosition(res,rej,{enableHighAccuracy:false,timeout:10000,maximumAge:600000}):rej());
  const {latitude:lat,longitude:lon}=pos.coords;
  const r=await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=temperature_2m,apparent_temperature,weather_code,wind_speed_10m&timezone=auto`);
  if(!r.ok)throw new Error('weather'); const d=await r.json(); const c=d.current;
  const place=await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${lat}&lon=${lon}&zoom=10&addressdetails=1`,{headers:{'Accept-Language':'de'}}).then(x=>x.json()).catch(()=>null);
  const a=place?.address||{}; const label=a.city||a.town||a.village||a.municipality||'Mein Standort';
  $('#weatherLocation').textContent=label; $('#weatherTemp').textContent=`${Math.round(c.temperature_2m)}°C ${weatherIcon(c.weather_code)}`; $('#weatherLabel').textContent=weatherText[c.weather_code]||'Aktuelles Wetter'; $('#weatherDetails').textContent=`Gefühlt ${Math.round(c.apparent_temperature)}°C · Wind ${Math.round(c.wind_speed_10m)} km/h`;
  btn.textContent='🔄 Wetter aktualisieren';
 }catch(e){$('#weatherLabel').textContent='Wetter nicht verfügbar';$('#weatherDetails').textContent='Standortfreigabe prüfen oder später erneut versuchen.';btn.textContent='📍 Erneut versuchen'} finally{btn.disabled=false}
}
if($('#loadWeather'))$('#loadWeather').onclick=loadWeather;
if($('#nextQuote'))$('#nextQuote').onclick=()=>{motivationIndex++;renderMotivation()};
renderMotivation();

const PIPELINE_STAGES=[['neu','Neu'],['kontaktiert','Kontakt'],['termin','Termin'],['angebot','Angebot'],['gewonnen','Gewonnen'],['verloren','Verloren']];
function setLeadStage(id,status){const l=S.leads.find(x=>x.id===id);if(!l)return;l.status=status;l.updatedAt=new Date().toISOString();if(status==='gewonnen')l.closedAt=new Date().toISOString();save();render();toast('Pipeline aktualisiert · '+sl(status))}
function renderPipeline(){const el=$('#pipelineBoard');if(!el)return;const active=S.leads.filter(l=>l.status!=='verloren');const won=S.leads.filter(l=>l.status==='gewonnen').length;const open=S.leads.filter(l=>!['gewonnen','verloren'].includes(l.status)).length;const due=S.tasks.filter(t=>!t.done&&t.due&&t.due<=today()).length;const offers=S.leads.filter(l=>l.status==='angebot').length;$('#pipelineSummary').innerHTML=`<div class="kpi"><span>Offen</span><b>${open}</b></div><div class="kpi"><span>Angebote</span><b>${offers}</b></div><div class="kpi"><span>Fällig</span><b>${due}</b></div><div class="kpi"><span>Gewonnen</span><b>${won}</b></div>`;el.innerHTML=PIPELINE_STAGES.map(([stage,label])=>{const arr=S.leads.filter(l=>l.status===stage);return `<div class="pipeline-column"><div class="pipeline-column-head"><h3>${label}</h3><span class="pipeline-count">${arr.length}</span></div>${arr.map(l=>`<article class="pipeline-lead"><h4>${esc(l.company)}</h4><div class="meta">${money(l.tpv)} TPV · ${esc(l.priority||'Mittel')}</div><div class="meta">${esc(l.next||'Nächsten Schritt festlegen')}${l.due?' · '+esc(l.due):''}</div><div class="pipeline-lead-actions"><button class="secondary" data-pipeline-edit="${l.id}">Öffnen</button><select class="stage-select" data-pipeline-stage="${l.id}">${PIPELINE_STAGES.map(([v,n])=>`<option value="${v}" ${v===l.status?'selected':''}>${n}</option>`).join('')}</select></div></article>`).join('')||'<div class="empty">Keine Leads</div>'}</div>`}).join('')}
$('#pipelineBoard')?.addEventListener('change',e=>{const id=e.target.dataset.pipelineStage;if(id)setLeadStage(id,e.target.value)});
$('#pipelineBoard')?.addEventListener('click',e=>{const id=e.target.closest('[data-pipeline-edit]')?.dataset.pipelineEdit;if(id)lead(id)});
function sumupLeadOnly(l){return l && !['vape'].includes(String(l.module||l.type||'').toLowerCase())}
function sumupTaskOnly(t){if(!t)return false;const m=String(t.module||t.type||'').toLowerCase();if(m==='vape')return false;const l=t.leadId&&S.leads.find(x=>x.id===t.leadId);return !m || m==='sumup' || !!l}
function sumupQuoteOnly(q){const m=String(q?.module||q?.type||'').toLowerCase();return m!=='vape'}
function renderDash(){
 const leads=S.leads.filter(sumupLeadOnly);
 const tasks=S.tasks.filter(sumupTaskOnly);
 const openTasks=tasks.filter(t=>!t.done);
 const overdue=openTasks.filter(t=>t.due&&t.due<today());
 const todayTasks=openTasks.filter(t=>t.due===today());
 const futureTasks=openTasks.filter(t=>t.due&&t.due>today());
 const openLeads=leads.filter(l=>!['gewonnen','verloren'].includes(l.status)).length;
 const appointments=leads.filter(l=>l.status==='termin').length;
 const won=leads.filter(l=>l.status==='gewonnen').length;
 const quotes=S.quotes.filter(sumupQuoteOnly).filter(q=>q.status!=='accepted');
 const potential=leads.filter(l=>!['verloren'].includes(l.status)).reduce((n,l)=>n+(Number(l.tpv)||0),0);
 const byStage=['neu','kontaktiert','termin','angebot','gewonnen'];
 const stageLabels={neu:'Neu',kontaktiert:'Kontakt',termin:'Termin',angebot:'Angebot',gewonnen:'Gewonnen'};
 const counts=Object.fromEntries(byStage.map(st=>[st,leads.filter(l=>l.status===st).length]));
 const total=leads.length;
 $('#kLeads').textContent=openLeads; $('#kTasks').textContent=overdue.length+todayTasks.length; $('#kAppts').textContent=appointments; $('#kWon').textContent=won; if($('#kQuotes'))$('#kQuotes').textContent=quotes.length;
 $('#pipelineTotal').textContent=`${total} ${total===1?'Lead':'Leads'}`;
 $('#pipelineBar').innerHTML=byStage.map(st=>`<div class="pipe-segment pipe-${st}" style="width:${total?Math.max(counts[st]/total*100,counts[st]?2:0):0}%" title="${stageLabels[st]}: ${counts[st]}"></div>`).join('');
 $('#pipelineLegend').innerHTML=byStage.map(st=>`<span><i class="dot dot-${st}"></i>${stageLabels[st]} <b>${counts[st]}</b></span>`).join('');
 const due=[...overdue,...todayTasks].sort((a,b)=>(a.due||'').localeCompare(b.due||'')).slice(0,5);
 $('#dashboardTasks').innerHTML=due.map(t=>{const l=t.leadId&&S.leads.find(x=>x.id===t.leadId);return `<button class="dash-task ${t.due<today()?'overdue':''}" data-dashboard-task="${t.id}"><div><b>${esc(t.title||t.type||'Aufgabe')}</b><span>${esc(l?.company||'SUMUP')}</span></div><strong>${t.due<today()?'Überfällig':'Heute'}</strong></button>`}).join('')||'<div class="empty">Keine dringenden Aufgaben. 🎉</div>';
 const b=[...leads].sort((x,y)=>(Number(y.tpv)||0)-(Number(x.tpv)||0))[0];
 $('#assistantCard').innerHTML=b?`<div class="row"><div><b>${esc(b.company)}</b><div class="meta">Größtes aktuelles TPV-Potenzial</div></div><span class="chip good">${money(b.tpv)}</span></div><p class="muted">${b.tpv>=5000?'Qualifiziert: Bedarf prüfen und Tarifvergleich durchführen.':'TPV unter internem Vertriebsziel: Potenzial verifizieren.'}</p><button class="secondary" data-edit="${b.id}">Lead öffnen</button>`:'<b>Bereit für den ersten Lead.</b><p class="muted">Erfasse einen Händler und der Sales Assistant priorisiert ihn automatisch.</p>';
 if($('#dashOverdue'))$('#dashOverdue').textContent=overdue.length;
 if($('#dashToday'))$('#dashToday').textContent=todayTasks.length;
 if($('#dashFuture'))$('#dashFuture').textContent=futureTasks.length;
 if($('#dashOffers'))$('#dashOffers').textContent=quotes.length;
 if($('#dashWon'))$('#dashWon').textContent=won;
 if($('#dashPotential'))$('#dashPotential').textContent=money(potential);
 if($('#dashActive'))$('#dashActive').textContent=leads.length;
}

$('#assistantCard').onclick=e=>{const id=e.target.closest('[data-edit]')?.dataset.edit;if(id)lead(id)};
async function geo(q){const r=await fetch('https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&countrycodes=de&q='+encodeURIComponent(q));const a=await r.json();if(!a[0])throw 0;return{lat:+a[0].lat,lon:+a[0].lon,label:a[0].display_name}}
const dist=(a,b)=>{const R=6371,r=x=>x*Math.PI/180,dlat=r(b.lat-a.lat),dlon=r(b.lon-a.lon),x=Math.sin(dlat/2)**2+Math.cos(r(a.lat))*Math.cos(r(b.lat))*Math.sin(dlon/2)**2;return 2*R*Math.asin(Math.sqrt(x))};
async function coords(l){if(Number.isFinite(+l.lat)&&Number.isFinite(+l.lon))return{lat:+l.lat,lon:+l.lon};try{const c=await geo(l.address);l.lat=c.lat;l.lon=c.lon;save();return c}catch{return null}}
function routeCustomerStats(c){const st=customerStats(c),lead=st.leads[0],date=$('#routeDate').value||today(),dueTasks=st.tasks.filter(t=>!t.done&&t.due&&t.due<=date);return{st,lead,dueTasks,sumup:st.leads.length>0||st.sumupQuotes.length>0,vape:st.vapeQuotes.length>0||st.invoices.length>0,priority:c.priority||lead?.priority||'Mittel'}}
function routeFilterMatch(c){const f=window.routeFilter||'all',x=routeCustomerStats(c),date=$('#routeDate').value||today();if(f==='due')return x.dueTasks.length>0||x.lead?.due===date||x.lead?.status==='termin';if(f==='sumup')return x.sumup;if(f==='vape')return x.vape;return true}
function priorityRank(v){return ({Hoch:0,Mittel:1,Niedrig:2}[v]??1)}
function optimizeRoute(items){const pool=[...items],out=[];let cur=area;while(pool.length){let best=0,bestScore=Infinity;for(let i=0;i<pool.length;i++){const d=dist(cur,pool[i]),score=d+priorityRank(pool[i]._stats.priority)*0.08;if(score<bestScore){bestScore=score;best=i}}const n=pool.splice(best,1)[0];out.push(n);cur=n}return out}
async function makeRoute(){if(!area)return;const rad=+$('#areaRadius').value||5,territory=($('#areaTerritory').value||'').trim().toLowerCase(),a=[];for(const c of S.customers){if(territory&&String(c.territory||'').trim().toLowerCase()!==territory)continue;if(!c.address||!routeFilterMatch(c))continue;const p=await coords(c);if(p&&dist(area,p)<=rad)a.push({...c,lat:p.lat,lon:p.lon,_stats:routeCustomerStats(c)})}route=optimizeRoute(a);renderRoute();$('#areaStatus').textContent=`${route.length} Kunden im Gebiet · ${rad} km${territory?' · '+territory:''}`}
function renderRoute(){const date=$('#routeDate')?.value||today();$('#routeCount').textContent=route.length;let total=0;for(let i=0;i<route.length;i++)total+=i?dist(route[i-1],route[i]):dist(area,route[i]);$('#routeSummary').innerHTML=route.length?`<b>${route.length} Stopps</b> · ca. ${total.toFixed(1)} km Luftlinie · ${fmtDate(date)} · Nähe + Priorität`: 'Noch keine Route zusammengestellt.';$('#routeList').innerHTML=route.map((c,i)=>{const x=c._stats||routeCustomerStats(c),due=x.dueTasks.length||x.lead?.due===date;return `<div class="route-item"><div class="route-main"><span class="route-no">${i+1}</span><div><b>${esc(c.company)}</b><div class="meta">${esc(c.address||'Keine Adresse')} · ${dist(area,c).toFixed(1)} km${c.territory?' · '+esc(c.territory):''}</div><div class="chips"><span class="chip ${x.sumup?'good':''}">🟠 ${x.sumup?'SUMUP aktiv':'SUMUP —'}</span><span class="chip ${x.vape?'good':''}">🟣 ${x.vape?'VAPE aktiv':'VAPE —'}</span><span class="chip ${x.priority==='Hoch'?'warn':''}">${esc(x.priority)} Priorität</span>${due?'<span class="chip warn">⏰ fällig</span>':''}</div></div></div><div class="route-buttons"><button class="icon-btn" data-route-up="${i}" ${i===0?'disabled':''}>↑</button><button class="icon-btn" data-route-down="${i}" ${i===route.length-1?'disabled':''}>↓</button><button class="secondary" data-route-nav="${c.id}">🧭</button><button class="secondary" data-route-customer="${c.id}">👤</button></div></div>`}).join('')||'<div class="empty">Keine Kunden passend zu Gebiet, Radius und Filter.</div>';$('#openRoute').disabled=!route.length;$('#saveRoute').disabled=!route.length;renderSavedRoutes()}
function moveRoute(i,delta){const j=i+delta;if(i<0||j<0||i>=route.length||j>=route.length)return;[route[i],route[j]]=[route[j],route[i]];renderRoute()}
function routeUrl(){if(!route.length)return '';const pts=route.map(x=>`${x.lat},${x.lon}`);return 'https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(`${area.lat},${area.lon}`)+'&destination='+encodeURIComponent(pts.at(-1))+'&waypoints='+encodeURIComponent(pts.slice(0,-1).join('|'))+'&travelmode=driving'}
function saveRoutePlan(){if(!route.length)return;const plan={id:uid(),date:$('#routeDate').value||today(),label:area?.label||'Gebiet',territory:$('#areaTerritory').value.trim(),radius:+$('#areaRadius').value||5,origin:{lat:area.lat,lon:area.lon,label:area.label},customerIds:route.map(x=>x.id),createdAt:new Date().toISOString()};S.routePlans=[plan,...S.routePlans.filter(x=>!(x.date===plan.date&&x.territory===plan.territory&&x.label===plan.label))].slice(0,20);save();renderSavedRoutes();toast('Tagesroute gespeichert')}
function renderSavedRoutes(){const el=$('#savedRoutes');if(!el)return;el.innerHTML=S.routePlans.map(p=>`<div class="saved-route"><div><b>${esc(fmtDate(p.date))} · ${esc(p.territory||p.label||'Gebiet')}</b><div class="meta">${p.customerIds.length} Kunden · ${p.radius} km Radius</div></div><div class="route-buttons"><button class="secondary" data-load-route="${p.id}">▶️ Laden</button><button class="secondary" data-open-saved-route="${p.id}">🧭 Maps</button><button class="icon-btn" data-delete-route="${p.id}">✕</button></div></div>`).join('')||'<div class="empty">Noch keine Route gespeichert.</div>'}
async function loadRoutePlan(id){const p=S.routePlans.find(x=>x.id===id);if(!p)return;area=p.origin;$('#areaQuery').value=p.label||'';$('#areaRadius').value=p.radius||5;$('#areaTerritory').value=p.territory||'';$('#routeDate').value=p.date||today();window.routeFilter='all';$$('[data-route-filter]').forEach(x=>x.classList.toggle('active',x.dataset.routeFilter==='all'));route=[];for(const cid of p.customerIds){const c=customerById(cid);if(!c||!c.address)continue;const co=await coords(c);if(co)route.push({...c,lat:co.lat,lon:co.lon,_stats:routeCustomerStats(c)})}renderRoute();$('#areaStatus').textContent=`Gespeicherte Route · ${route.length} Kunden`}
async function prospects(){if(!area)return;$('#prospectList').innerHTML='<div class="muted">Unternehmen werden gesucht …</div>';try{const u=`https://overpass-api.de/api/interpreter?data=[out:json][timeout:20];(nwr["shop"](around:${(+$('#areaRadius').value||5)*1000},${area.lat},${area.lon});nwr["amenity"~"cafe|restaurant"](around:${(+$('#areaRadius').value||5)*1000},${area.lat},${area.lon});nwr["shop"="convenience"](around:${(+$('#areaRadius').value||5)*1000},${area.lat},${area.lon}););out center tags 80;`;const r=await fetch(u);const j=await r.json();const arr=j.elements.filter(x=>x.tags?.name).slice(0,30).map(x=>({name:x.tags.name,address:[x.tags['addr:street'],x.tags['addr:housenumber'],x.tags['addr:postcode'],x.tags['addr:city']].filter(Boolean).join(' '),lat:x.lat??x.center?.lat,lon:x.lon??x.center?.lon}));$('#prospectList').innerHTML=arr.map(p=>`<div class="prospect"><div><b>${esc(p.name)}</b><div class="meta">${esc(p.address||'Adresse nicht angegeben')}</div></div><button class="secondary" data-prospect="${encodeURIComponent(JSON.stringify(p))}">＋ Lead</button></div>`).join('')||'<div class="empty">Keine Treffer im öffentlichen Datenbestand.</div>'}catch{$('#prospectList').innerHTML='<div class="empty">Gebietssuche derzeit nicht verfügbar.</div>'}}
$('#routeDate').value=today();window.routeFilter='all';
$('#searchArea').onclick=async()=>{const q=$('#areaQuery').value.trim();if(!q)return toast('PLZ oder Ort eingeben');$('#areaStatus').textContent='Gebiet wird ermittelt …';try{area=await geo(q);$('#areaStatus').textContent=area.label;await makeRoute();await prospects()}catch{$('#areaStatus').textContent='Gebiet nicht gefunden';toast('Ort/PLZ nicht gefunden')}};
$('#useLocation').onclick=()=>navigator.geolocation?.getCurrentPosition(async p=>{area={lat:p.coords.latitude,lon:p.coords.longitude,label:'Mein Standort'};$('#areaStatus').textContent='Mein Standort';await makeRoute();await prospects()},()=>toast('Standortzugriff nicht möglich'));
