$('#routeList').onclick=e=>{let i=e.target.closest('[data-route-up]')?.dataset.routeUp;if(i!=null)return moveRoute(+i,-1);i=e.target.closest('[data-route-down]')?.dataset.routeDown;if(i!=null)return moveRoute(+i,1);const navId=e.target.closest('[data-route-nav]')?.dataset.routeNav;if(navId){const c=customerById(navId);if(c?.address)window.open('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(c.address),'_blank');return}const cid=e.target.closest('[data-route-customer]')?.dataset.routeCustomer;if(cid)return openCustomer(cid)};
$('#openRoute').onclick=()=>{const u=routeUrl();if(u)window.open(u,'_blank')};$('#saveRoute').onclick=saveRoutePlan;
$('#savedRoutes').onclick=async e=>{const id=e.target.closest('[data-load-route]')?.dataset.loadRoute;if(id)return loadRoutePlan(id);const did=e.target.closest('[data-delete-route]')?.dataset.deleteRoute;if(did&&confirm('Gespeicherte Route löschen?')){S.routePlans=S.routePlans.filter(x=>x.id!==did);save();renderSavedRoutes();return}const oid=e.target.closest('[data-open-saved-route]')?.dataset.openSavedRoute;if(oid){const p=S.routePlans.find(x=>x.id===oid);if(!p)return;const pts=p.customerIds.map(id=>customerById(id)).filter(c=>Number.isFinite(+c?.lat)&&Number.isFinite(+c?.lon)).map(c=>`${c.lat},${c.lon}`);if(p.origin&&pts.length)window.open('https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(`${p.origin.lat},${p.origin.lon}`)+'&destination='+encodeURIComponent(pts.at(-1))+'&waypoints='+encodeURIComponent(pts.slice(0,-1).join('|'))+'&travelmode=driving','_blank')}};
$('#prospectList').onclick=e=>{const b=e.target.closest('[data-prospect]');if(!b)return;const p=JSON.parse(decodeURIComponent(b.dataset.prospect));$('#leadForm').reset();$('#leadId').value='';$('#leadDialogTitle').textContent='Neuer SUMUP-Lead aus Gebiet';$('#fCompany').value=p.name;const pa=splitAddress(p.address||'');$('#fStreet').value=pa.street;$('#fZip').value=pa.zip;$('#fCity').value=pa.city;$('#fDue').value=today();$('#fStatus').value='neu';$('#fPriority').value='Mittel';hint();open('leadDialog')};
const SUMUP_INTERNAL_THRESHOLD=5000;
const SUMUP_HARDWARE=[
  {price:0,name:'Keine Hardware'},
  {price:34,name:'Solo Lite'},
  {price:79,name:'Solo'},
  {price:169,name:'Terminal'},
  {price:399,name:'SumUp Kasse / Register'}
];
function pricing(){ $('#pTpv').value=5000;$('#pHardwareDiscount').value=25;$('#pHardwareExtra').value=0;calcPricing();open('pricingDialog') }
function calcPricing(){
  const tpv=+$('#pTpv').value||0,rate=+$('#pCurrentRate').value||0,fixed=+$('#pCurrentFixed').value||0;
  const hardwareList=+$('#pHardware').value||0;
  const requestedDiscount=Math.min(25,Math.max(0,+$('#pHardwareDiscount').value||0));
  $('#pHardwareDiscount').value=requestedDiscount;
  const hardwareDiscount=hardwareList*requestedDiscount/100;
  const hardwareSale=hardwareList-hardwareDiscount;
  const hardwareExtra=Math.max(0,+$('#pHardwareExtra').value||0);
  const oneTimeHardware=hardwareSale+hardwareExtra;
  const current=tpv*rate/100+fixed;
  const payg=tpv*0.0139;
  const plus=tpv*0.0079+19;
  const plans=[
    {key:'payg',name:'SumUp umsatzbasiertes Zahlen',monthly:payg,description:'1,39 % auf Kartenzahlungen · 0 € Monatsgebühr',fee:'1,39%',fixed:0},
    {key:'plus',name:'SumUp Zahlungen Plus',monthly:plus,description:'0,79 % auf berechtigte EWR-Verbraucherkarten · 19 € Monatsgebühr',fee:'0,79%',fixed:19}
  ];
  const recommended=tpv>=SUMUP_INTERNAL_THRESHOLD?'plus':'payg';
  const hwLine=hardwareList?`<small>Hardware: ${money(hardwareList)} − ${money(hardwareDiscount)} Rabatt = <b>${money(hardwareSale)}</b>${hardwareExtra?` · Zubehör/Einmalgebühr: ${money(hardwareExtra)}`:''}</small>`:(hardwareExtra?`<small>Zubehör/Einmalgebühr: <b>${money(hardwareExtra)}</b> · rabattfrei</small>`:'<small>Keine einmalige Hardware hinterlegt</small>');
  $('#pricingResult').innerHTML=
    `<div class="result"><b>Aktuell</b><strong>${money(current)}/Monat</strong><small>nach deinen Eingaben</small></div>`+
    `<div class="result"><b>Einmalige Hardware</b><strong>${money(oneTimeHardware)}</strong>${hwLine}</div>`+
    plans.map(p=>{const firstMonth=p.monthly+oneTimeHardware,firstYear=p.monthly*12+oneTimeHardware;return `<div class="result tariff-result"><div><b>${esc(p.name)} ${p.key===recommended?'· EMPFOHLEN':''}</b><strong>${money(p.monthly)}/Monat</strong><small>${esc(p.description)}</small><small>1. Monat inkl. Hardware: <b>${money(firstMonth)}</b> · 1. Jahr inkl. Hardware: <b>${money(firstYear)}</b></small></div><button class="primary" data-use-tariff="${p.key}">💼 Ins Angebot</button></div>`}).join('')+
    `<div class="qual-box qual-${recommended==='plus'?'A':'B'}"><b>Vertriebsempfehlung bei ${money(tpv)} TPV</b><br>${recommended==='plus'?'Zahlungen Plus':'Umsatzbasiertes Zahlen'} anhand der neXaro 5.000-€-Schwelle. <span class="muted">Die Hardware wird zusätzlich einmalig gerechnet und ist nicht Teil der monatlichen Tarifgebühr.</span></div>`;
}
$('#pTpv').oninput=calcPricing;$('#pCurrentRate').oninput=calcPricing;$('#pCurrentFixed').oninput=calcPricing;$('#pHardware').onchange=calcPricing;$('#pHardwareDiscount').oninput=calcPricing;$('#pHardwareExtra').oninput=calcPricing;
$('#pricingResult').onclick=e=>{
  const b=e.target.closest('[data-use-tariff]');
  if(!b)return;
  const tpv=+$('#pTpv').value||0;
  const key=b.dataset.useTariff;
  const hardwareList=+$('#pHardware').value||0;
  const hardwareDiscount=Math.min(25,Math.max(0,+$('#pHardwareDiscount').value||0));
  const hardwareSale=hardwareList-(hardwareList*hardwareDiscount/100);
  const hardwareExtra=Math.max(0,+$('#pHardwareExtra').value||0);
  const items=[];
  if(key==='plus')items.push({description:'SumUp Zahlungen Plus – Monatsgebühr',qty:1,unit:'Monat',price:19,note:`SumUp Zahlungen Plus: 0,79 % auf berechtigte EWR-Verbraucherkarten. Berechnungsbasis: ${money(tpv)} monatliches Kartenzahlungsvolumen.`});
  else items.push({description:'SumUp umsatzbasiertes Zahlen – Monatsgebühr',qty:1,unit:'Monat',price:0,note:`SumUp umsatzbasiertes Modell: 1,39 % auf Kartenzahlungen, 0 € Monatsgebühr. Berechnungsbasis: ${money(tpv)} monatliches Kartenzahlungsvolumen.`});
  if(hardwareList){const name=SUMUP_HARDWARE.find(x=>x.price===hardwareList)?.name||'SumUp Hardware';items.push({description:`${name} – einmalige Hardware`,qty:1,unit:'Stück',price:hardwareSale,note:`Offizieller Listenpreis ${money(hardwareList)} · eigener neXaro Hardware-Rabatt ${hardwareDiscount}% · Angebotspreis ${money(hardwareSale)}.`})}
  if(hardwareExtra)items.push({description:'Sonstiges Zubehör / Einmalgebühr',qty:1,unit:'Stück',price:hardwareExtra,note:'Einmalige Gebühr · kein Hardware-Rabatt hinterlegt.'});
  const tariff={description:key==='plus'?'SumUp Zahlungen Plus – Monatsgebühr':'SumUp umsatzbasiertes Zahlen – Monatsgebühr',qty:1,unit:'Monat',price:key==='plus'?19:0,note:`SumUp Deutschland · neXaro Vertriebsschwelle 5.000 € · TPV ${money(tpv)}.`};
  close('pricingDialog');
  quote(null,null,{tariff,tariffKey:key,tpv,items});
};
function commission(){calcCommission();open('commissionDialog')}
function calcCommission(){const tpv=+$('#cTpv').value||0,hw=+$('#cHardware').value||0,sw=+$('#cSoftware').value||0,activation=tpv>=500?200:0,pay=(tpv*0.007*12)*0.5,topup30=Math.max(0,pay-activation),hardware=hw*0.5,software=sw*12*0.5,bonus=(+$('#cContracts').value?100:0)+(+$('#cPos').value?100:0)+(+$('#cChampion').value?100:0)+(+$('#cMaster').value?100:0),total=activation+topup30+hardware+software+bonus;$('#commissionResult').innerHTML=`<div class="result"><b>Aktivierung</b><strong>${money(activation)}</strong></div><div class="result"><b>Payments Top-Up 30</b><strong>${money(topup30)}</strong><small>mit 0,7% angenommener Net Revenue Margin</small></div><div class="result"><b>Hardware</b><strong>${money(hardware)}</strong></div><div class="result"><b>Software</b><strong>${money(software)}</strong></div><div class="result"><b>Boni</b><strong>${money(bonus)}</strong></div><div class="result"><b>Interne Deal-Summe</b><strong>${money(total)}</strong><small>Nur intern · Vertragsbedingungen haben Vorrang</small></div>`}
$$('#commissionDialog input,#commissionDialog select').forEach(x=>x.oninput=calcCommission);


const VAT_RATE=0.19;
const calcTotals=items=>{const net=(items||[]).reduce((s,i)=>s+(Number(i.qty)||0)*(Number(i.price)||0),0);return {net,vat:net*VAT_RATE,gross:net*(1+VAT_RATE)}};
const fmtDate=d=>d?new Intl.DateTimeFormat("de-DE").format(new Date(d+"T12:00:00")):"";
const nextDate=days=>{const d=new Date();d.setDate(d.getDate()+days);return d.toISOString().slice(0,10)};
const itemTemplate=(item={},idx=0)=>`<div class="line-item" data-index="${idx}"><div class="line-index">${idx+1}</div><input class="li-desc" placeholder="Bezeichnung / Leistung" value="${esc(item.description||item.product||"")}"><input class="li-qty" type="number" min="0" step="0.01" placeholder="Menge" value="${item.qty??1}"><input class="li-unit" placeholder="Einheit" value="${esc(item.unit||"Stück")}"><input class="li-price" type="number" min="0" step="0.01" placeholder="Einzel €" value="${item.price??0}"><div class="li-total">0,00 €</div><button type="button" class="icon-btn remove-line">✕</button></div>`;
function getItems(id){return [...document.querySelectorAll(`#${id} .line-item`)].map(r=>({description:r.querySelector(".li-desc").value.trim(),qty:+r.querySelector(".li-qty").value||0,unit:r.querySelector(".li-unit").value.trim()||"Stück",price:+r.querySelector(".li-price").value||0})).filter(i=>i.description||i.price)};
function recalcItems(id,netId,vatId,grossId){const rows=[...document.querySelectorAll(`#${id} .line-item`)],items=[];rows.forEach((r,i)=>{r.querySelector(".line-index").textContent=i+1;const q=+r.querySelector(".li-qty").value||0,p=+r.querySelector(".li-price").value||0;r.querySelector(".li-total").textContent=money(q*p);items.push({qty:q,price:p})});const t=calcTotals(items);$("#"+netId).textContent=money(t.net);$("#"+vatId).textContent=money(t.vat);$("#"+grossId).textContent=money(t.gross)}
function addItem(id,item={}){const c=document.getElementById(id);c.insertAdjacentHTML("beforeend",itemTemplate(item,c.children.length));const r=c.lastElementChild;r.querySelectorAll("input").forEach(x=>x.addEventListener("input",()=>recalcItems(id,id.includes("quote")?"qNetPreview":"iNetPreview",id.includes("quote")?"qVatPreview":"iVatPreview",id.includes("quote")?"qGrossPreview":"iGrossPreview")));r.querySelector(".remove-line").onclick=()=>{r.remove();if(!c.children.length)addItem(id);recalcItems(id,id.includes("quote")?"qNetPreview":"iNetPreview",id.includes("quote")?"qVatPreview":"iVatPreview",id.includes("quote")?"qGrossPreview":"iGrossPreview")}}
function fillItems(id,items){const c=document.getElementById(id);c.innerHTML="";(items&&items.length?items:[{}]).forEach(i=>addItem(id,i));recalcItems(id,id.includes("quote")?"qNetPreview":"iNetPreview",id.includes("quote")?"qVatPreview":"iVatPreview",id.includes("quote")?"qGrossPreview":"iGrossPreview")}
function quote(id=null,leadId=null,preset=null){
  $("#quoteForm").reset();
  $("#qCustomer").innerHTML=customerOptions();
  $("#qLead").innerHTML='<option value="">Ohne Lead</option>'+S.leads.map(l=>`<option value="${l.id}">${esc(l.company)}</option>`).join("");
  $("#quoteId").value=id||"";
  let q=id&&S.quotes.find(x=>x.id===id);
  if(!q&&leadId){
    const l=S.leads.find(x=>x.id===leadId);
    q={leadId:l.id,company:l.company,contact:l.contact,email:l.email,items:[{description:l.product||"SumUp Lösung",qty:1,unit:"Stück",price:0}],date:today(),validUntil:nextDate(14),status:"draft"};
  }
  if(!q&&preset){
    q={company:"",contact:"",email:"",items:preset.items?.length?preset.items:[preset.tariff],date:today(),validUntil:nextDate(14),status:"draft",note:`${preset.tariff.note||""} Einmalige Hardware wird separat berücksichtigt.`};
  }
  if(q){
    $("#qCustomer").value=q.customerId||S.leads.find(l=>l.id===q.leadId)?.customerId||"";
    $("#qLead").value=q.leadId||"";
    $("#qCompany").value=q.company||"";
    $("#qCustomerNo").value=q.customerNo||"";
    $("#qContact").value=q.contact||"";
    $("#qVatId").value=q.vatId||"";
    $("#qEmail").value=q.email||"";
    $("#qDate").value=q.date||today();
    $("#qValidUntil").value=q.validUntil||nextDate(14);
    $("#qStatus").value=q.status||"draft";
    $("#qNote").value=q.note||"";
    fillItems("quoteItems",q.items||[]);
  }else{
    $("#qDate").value=today();
    $("#qValidUntil").value=nextDate(14);
    $("#qStatus").value="draft";
    fillItems("quoteItems");
  }
  open("quoteDialog")
}
$("#qCustomer").onchange=()=>{const c=customerById($("#qCustomer").value);if(!c)return;$("#qCompany").value=c.company||"";$("#qCustomerNo").value=c.customerNo||"";$("#qContact").value=c.contact||"";$("#qVatId").value=c.vatId||"";$("#qEmail").value=c.email||"";const l=S.leads.find(x=>x.customerId===c.id);$("#qLead").value=l?.id||""};
$("#qLead").onchange=()=>{
  const l=S.leads.find(x=>x.id===$("#qLead").value);
  if(!l)return;
  ensureCustomerForLead(l.id);
  $("#qCustomer").innerHTML=customerOptions(l.customerId||"");
  $("#qCustomer").value=l.customerId||"";
  $("#qCompany").value=l.company||"";
  $("#qContact").value=l.contact||"";
  $("#qEmail").value=l.email||"";
  if(!$("#quoteItems .li-desc").length || !$("#quoteItems .li-desc").first().value){
    fillItems("quoteItems",[{description:l.product&&l.product!=="Noch offen"?`SumUp ${l.product}`:"SumUp Lösung",qty:1,unit:"Stück",price:0}]);
  }
};
$("#addQuoteItem").onclick=()=>{addItem("quoteItems");recalcItems("quoteItems","qNetPreview","qVatPreview","qGrossPreview")};
$("#quoteForm").onsubmit=e=>{e.preventDefault();const items=getItems("quoteItems"),t=calcTotals(items),leadId=$("#qLead").value,customer=customerById($("#qCustomer").value)||ensureCustomerForLead(leadId),d={id:$("#quoteId").value||uid(),leadId,customerId:customer?.id||"",company:$("#qCompany").value.trim(),customerNo:$("#qCustomerNo").value.trim(),contact:$("#qContact").value.trim(),vatId:$("#qVatId").value.trim(),email:$("#qEmail").value.trim(),items,net:t.net,vat:t.vat,gross:t.gross,date:$("#qDate").value,validUntil:$("#qValidUntil").value,status:$("#qStatus").value,note:$("#qNote").value.trim()};const i=S.quotes.findIndex(x=>x.id===d.id);if(i<0){S.quoteSequence=(S.quoteSequence||0)+1;d.number="AG"+String(S.quoteSequence).padStart(4,"0");}else d.number=S.quotes[i].number||("AG"+String(i+1).padStart(4,"0"));i>=0?S.quotes[i]={...S.quotes[i],...d}:S.quotes.unshift(d);const l=S.leads.find(x=>x.id===d.leadId);if(l&&l.status!=="gewonnen")l.status="angebot";save();close("quoteDialog");render();toast("Angebot gespeichert")};
function docs(){$("#quoteList").innerHTML=S.quotes.map(x=>`<div class="card"><div class="row"><div><b>Angebot · ${esc(x.company)}</b><div class="meta">${(x.items||[]).length} Position(en) · ${money(x.gross)} brutto · ${esc(fmtDate(x.date))}${x.validUntil?" · gültig bis "+esc(fmtDate(x.validUntil)):""}</div></div><span class="badge">${esc(x.status||"draft")}</span></div><div class="lead-actions"><button data-pdfquote="${x.id}">📄 PDF / Drucken</button><button data-mailquote="${x.id}">✉️ E-Mail</button><button data-editquote="${x.id}">✏️</button></div></div>`).join("")||'<div class="empty">Noch keine Angebote.</div>'}
function printDocument(kind,id){const d=S.quotes.find(x=>x.id===id);if(!d)return;const items=d.items||[],t=calcTotals(items),title="ANGEBOT",number=d.number||("AG"+String(S.quotes.indexOf(d)+1).padStart(4,"0")),lead=S.leads.find(x=>x.id===d.leadId)||{},rows=items.map((i,n)=>`<tr><td>${n+1}</td><td><b>${esc(i.description)}</b></td><td class="right">${esc(i.qty)}</td><td>${esc(i.unit||"")}</td><td class="right">${money(i.price)}</td><td class="right">${money((+i.qty||0)*(+i.price||0))}</td></tr>`).join(""),recipient=`<div class="senderline">neXaro Solutions, Kirchstraße 1A, 15757 Halbe</div><div class="recipient"><b>${esc(d.company||lead.company||"")}</b><br>${esc(d.contact||lead.contact||"")}<br>${esc(lead.address||"")}${d.email?`<br>${esc(d.email)}`:""}</div>`,meta=`<div class="meta-grid"><div><b>Angebotsnr.:</b><span>${esc(number)}</span></div><div><b>Kundennr.:</b><span>${esc(d.customerNo||lead.customerNo||"")}</span></div><div><b>Kunden-USt-IdNr.:</b><span>${esc(d.vatId||lead.vatId||"")}</span></div><div><b>Datum:</b><span>${esc(fmtDate(d.date))}</span></div><div><b>gültig bis:</b><span>${esc(fmtDate(d.validUntil))}</span></div></div>`;const logoData="data:image/png;base64,";const w=window.open("","_blank","width=1000,height=1200");if(!w){toast("Popup blockiert – bitte Popups erlauben");return}w.document.write(`<!doctype html><html lang="de"><head><meta charset="utf-8"><title>Angebot ${esc(number)} · neXaro Solutions</title><style>@page{size:A4;margin:12mm 14mm 18mm}*{box-sizing:border-box}body{margin:0;color:#111;font:12px Arial,Helvetica,sans-serif}.page{max-width:182mm;margin:0 auto;padding-top:2mm}.letterhead{display:flex;justify-content:space-between;align-items:flex-start;min-height:40mm}.head-right{text-align:right;line-height:1.45}.logo{width:43mm;height:auto;margin-bottom:3mm}.senderline{font-size:9px;text-decoration:underline;margin-top:8mm}.recipient{margin-top:5mm;min-height:27mm;line-height:1.45}.title{font-size:20px;font-weight:400;margin:8mm 0 3mm}.intro{font-size:12px;margin-bottom:6mm}.meta-grid{display:grid;grid-template-columns:1.1fr .9fr 1.5fr 1fr 1fr;border-top:1px solid #111;border-bottom:1px solid #111;margin-bottom:9mm}.meta-grid>div{padding:3mm 2mm;display:flex;flex-direction:column;gap:1.2mm}.meta-grid b{font-size:10px}.meta-grid span{font-size:11px}table{width:100%;border-collapse:collapse;font-size:11px}th,td{border:1px solid #222;padding:2.7mm 2mm;vertical-align:top}th{font-weight:700;text-align:left}th.right,td.right{text-align:right}.totals{width:52%;margin:8mm 0 0 auto}.totals div{display:flex;justify-content:space-between;padding:2.2mm 2mm;border-bottom:1px solid #bbb}.totals .grand{font-size:13px;font-weight:700;border-top:1.5px solid #111;border-bottom:1.5px solid #111}.note{margin-top:8mm;white-space:pre-wrap}.footer{margin-top:18mm;border-top:1px solid #111;padding-top:3mm;display:grid;grid-template-columns:1fr 1fr 1fr;gap:7mm;font-size:8.5px;line-height:1.35}.printbar{text-align:right;margin-top:8mm}.printbar button{background:#111;color:#fff;border:0;padding:10px 16px;border-radius:6px;font-weight:700}@media print{.printbar{display:none}.page{max-width:none}.footer{break-inside:avoid}tr{break-inside:avoid}}</style></head><body><div class="page"><header class="letterhead"><div></div><div class="head-right"><img class="logo" src="${logoData}"><br>neXaro Solutions<br>Kirchstraße 1A<br>15757 Halbe<br><br>Kontakt@nexaro-solutions.de<br>www.nexaro-solutions.de</div></header>${recipient}<h1 class="title">Angebot - ${esc(d.company||"")}</h1><div class="intro">Gerne bieten wir Ihnen an:</div>${meta}<table><thead><tr><th style="width:7%">Pos.</th><th>Bezeichnung</th><th style="width:10%" class="right">Menge</th><th style="width:11%">Einheit</th><th style="width:14%" class="right">Einzel €</th><th style="width:16%" class="right">Gesamt €</th></tr></thead><tbody>${rows}</tbody></table><div class="totals"><div><span>Zwischensumme</span><b>${money(t.net)}</b></div><div><span>Umsatzsteuer 19 %</span><b>${money(t.vat)}</b></div><div class="grand"><span>Gesamtbetrag</span><b>${money(t.gross)}</b></div></div>${d.note?`<div class="note">${esc(d.note)}</div>`:""}<p style="margin-top:8mm">Wir freuen uns auf Ihre Auftragserteilung und sichern eine einwandfreie Ausführung zu.</p><footer class="footer"><div>neXaro Solutions<br>Kirchstraße 1A<br>15757 Halbe<br>Kontakt@nexaro-solutions.de<br>www.nexaro-solutions.de</div><div>USt-IdNr.: DE367084019<br>Steuernummer: 049/295/08926<br>Finanzamt Königs Wusterhausen<br>Einzelunternehmen<br>Inhaber: Sebastian Pötschke</div><div>SEBASTIAN POETSCHKE<br>N26<br>Die Bankverbindung wird aus Datenschutzgründen nicht im öffentlichen GitHub-Code hinterlegt.</div></footer><div class="printbar"><button onclick="window.print()">📄 Drucken / Als PDF speichern</button></div></div></body></html>`);w.document.close();w.focus()}
function mailQuote(id){const q=S.quotes.find(x=>x.id===id),t=calcTotals(q.items||[]);location.href=`mailto:${encodeURIComponent(q.email||"")}?subject=${encodeURIComponent("Angebot AG"+String(S.quotes.indexOf(q)+1).padStart(4,"0")+" – neXaro Solutions")}&body=${encodeURIComponent(`Hallo ${q.contact||q.company},\n\nanbei unser Angebot von neXaro Solutions.\n\nGesamt brutto: ${money(t.gross)}\nGültig bis: ${fmtDate(q.validUntil)}\n\nFreundliche Grüße\nneXaro Solutions`)}`}
$("#quoteList").onclick=e=>{let id=e.target.closest("[data-pdfquote]")?.dataset.pdfquote;if(id)return printDocument("quote",id);id=e.target.closest("[data-editquote]")?.dataset.editquote;if(id)return quote(id);id=e.target.closest("[data-mailquote]")?.dataset.mailquote;if(id)mailQuote(id)};

function csv(){const rows=[['Firma','Branche','Status','Kontakt','Telefon','E-Mail','Adresse','TPV','Qualifizierung','Produkt','Priorität','Nächste Aktion','Nächster Kontakt'],...S.leads.map(l=>[l.company,l.industry,l.status,l.contact,l.phone,l.email,l.address,l.tpv,l.qualification,l.product,l.priority,l.next,l.due])];download('nexaro-leads.csv',rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(';')).join('\n'),'text/csv;charset=utf-8')}
function download(name,data,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
