const L3_RULES = [
 ['eb800','VP001'],['bm600','VP002'],['qm600','VP002'],
 ['elfa turbo pro','VP022'],['elfa turbo','VP016'],['elfa master limited','VP010'],['elfa master','VP009'],
 ['tappo eol','VP008'],['tappo','VP005'],['elfa new 1. july','VP004'],['elfa limited','VP006'],
 ['elfa refillable pod','VP011'],['elfa pod','VP003'],['elfa basisgerät','VP003'],['elfa','VP003'],
 ['elfx mega 10ml','VP020'],['elfx mega 5ml','VP021'],['elfx mega','VP025'],['elfx pro','VP018'],['elfx mini','VP023'],['elfx 2','VP024'],['elfx v2.0','VP012'],['elfx','VP017'],
 ['elfliq','VP013'],['elfbar max','VP015']
];
S.vapeProducts = VAPE_PRODUCTS.map(p=>({...p}));
S.vapeCart=(S.vapeCart||[]).filter(x=>S.vapeProducts.some(p=>p.id===x.productId));
S.vapeQuotes=S.vapeQuotes||[]; S.vapeInvoices=S.vapeInvoices||[];
S.vapeQuoteSequence=S.vapeQuoteSequence||0; S.vapeInvoiceSequence=S.vapeInvoiceSequence||0;
S.leads.forEach(l=>{if(l.customerId&&!customerById(l.customerId))l.customerId=null;if(l.status==='gewonnen'&&!l.customerId)ensureCustomerForLead(l.id)});
S.customers.forEach(c=>{const l=S.leads.find(x=>x.customerId===c.id);if(l)c.sourceLeadId=l.id});

S.vapeMarkup=Math.min(25,Math.max(15,Number(S.vapeMarkup)||25));
S.vapePrivatePrices=S.vapePrivatePrices||{};
function privateEk(p){const key=matchL3Key(p);const ek=key?Number(S.vapePrivatePrices?.[key]):NaN;return Number.isFinite(ek)&&ek>=0?ek:null}
function matchL3Key(p){const x=((p?.name||'')+' '+(p?.variant||'')).toLowerCase().replace(/\s+/g,' ');for(const [needle,key] of L3_RULES)if(x.includes(needle))return key;return null}
function vapePrice(p){const ek=privateEk(p);return ek!==null?Math.round(ek*(1+S.vapeMarkup/100)*100)/100:null}
function cartCount(){return S.vapeCart.reduce((n,x)=>n+(+x.qty||0),0)}
function addToVapeCart(productId,qty=1){const p=S.vapeProducts.find(x=>x.id===productId),price=vapePrice(p);if(!p||price===null)return toast("Kein VK verfügbar – L3-Zuordnung prüfen");const q=Math.max(1,+qty||1),item=S.vapeCart.find(x=>x.productId===productId);if(item){item.qty+=q;item.price=price}else S.vapeCart.push({productId:p.id,name:p.name,variant:p.variant||"",qty:q,price});save();renderVape();toast(`${q} × ${p.name} im Warenkorb`)}
function updateVapeCart(productId,delta){const item=S.vapeCart.find(x=>x.productId===productId);if(!item)return;item.qty+=delta;if(item.qty<=0)S.vapeCart=S.vapeCart.filter(x=>x.productId!==productId);save();renderVape()}
function clearVapeCart(){S.vapeCart=[];save();renderVape();toast("Warenkorb geleert")}
function cartItems(){return S.vapeCart.map(x=>({productId:x.productId,description:x.name,variant:x.variant,qty:x.qty,unit:"Stück",price:x.price,ek:privateEk(S.vapeProducts.find(p=>p.id===x.productId))})).filter(x=>x.qty>0&&x.price>0)}
function openVapeCartQuote(){if(!cartItems().length)return toast("Warenkorb ist leer");newVapeQuoteFromCart()}
function newVapeQuoteFromCart(){S._quoteFromCart=true;newVapeQuote(null,null,null,cartItems())}
function vapeMargin(p){const ek=privateEk(p),vk=vapePrice(p);return ek!==null&&vk?1-ek/vk:null}
function setVapeMarkup(v){S.vapeMarkup=Math.min(25,Math.max(15,Number(v)||25));S.vapeCart=S.vapeCart.map(x=>{const p=S.vapeProducts.find(y=>y.id===x.productId),price=vapePrice(p);return price===null?x:{...x,price}});save();renderVape();}
function vapeProductOptions(){return '<option value="">Artikel wählen …</option>'+S.vapeProducts.map(p=>{const vk=vapePrice(p);return `<option value="${p.id}">${esc(p.name)} · ${vk===null?'VK —':`VK ${money(vk)}`}</option>`}).join('')}
function exportPrivateL3(){const payload={version:2,source:'L3-Preisliste des Nutzers',prices:S.vapePrivatePrices};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='nexaro-private-l3-prices.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function importPrivateL3(file){if(!file)return;const r=new FileReader();r.onload=()=>{try{const d=JSON.parse(r.result);if(!d||typeof d.prices!=='object')throw 0;S.vapePrivatePrices={...d.prices};S.vapeCart=S.vapeCart.map(x=>{const p=S.vapeProducts.find(y=>y.id===x.productId),price=vapePrice(p);return price===null?x:{...x,price}});save();renderVape();toast(`${Object.keys(S.vapePrivatePrices).length} L3-Preise importiert`)}catch{toast('L3-Datei konnte nicht gelesen werden')}};r.readAsText(file)}
function parseCSV(text){const rows=[];let row=[],cell='',q=false;for(let i=0;i<text.length;i++){const ch=text[i],nx=text[i+1];if(ch==='"'){if(q&&nx==='"'){cell+='"';i++}else q=!q}else if((ch===','||ch===';')&&!q){row.push(cell);cell=''}else if((ch==='\n'||ch==='\r')&&!q){if(ch==='\r'&&nx==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell=''}else cell+=ch}if(cell||row.length){row.push(cell);rows.push(row)}return rows}
function importDealerCSV(file){if(!file)return;const r=new FileReader();r.onload=()=>{try{const rows=parseCSV(String(r.result).replace(/^\uFEFF/,''));const head=rows.shift().map(x=>x.trim().replace(/^="(.*)"$/,'$1'));const ix=Object.fromEntries(head.map((h,i)=>[h,i]));const raw=rows.map(r=>({Bestellnummer:(r[ix.Bestellnummer]||'').replace(/^="(.*)"$/,'$1'),Menge:(r[ix.Menge]||'').replace(/^="(.*)"$/,'$1'),EAN:(r[ix.EAN]||'').replace(/^="(.*)"$/,'$1'),Name:(r[ix.Name]||'').replace(/^="(.*)"$/,'$1'),Variante:(r[ix.Variante]||'').replace(/^="(.*)"$/,'$1')}));const keep=raw.map(x=>{const t=(x.Name+' '+x.Variante).toLowerCase();let category='';if(t.includes('elfliq')||(t.includes('elfa')&&t.includes('liquid')))category='ELFA-Liquid';else if(t.includes('einweg'))category='Einwegzigaretten';else if(t.includes('prefilled pod')||t.includes('prefill pod'))category='Prefilled Pods';else if(t.includes('akkuträger')||t.includes('akkutraeger'))category='Akkuträger';return category?{...x,category}:null}).filter(Boolean);S.vapeProducts=keep.map((x,i)=>({id:'CAT'+String(i+1).padStart(5,'0'),name:x.Name,variant:x.Variante,category:x.category,orderNo:x.Bestellnummer,ean:x.EAN,qty:x.Menge}));S.vapeCart=(S.vapeCart||[]).filter(x=>S.vapeProducts.some(p=>p.id===x.productId));save();renderVape();toast(`${S.vapeProducts.length} Vape-Artikel importiert`)}catch{toast('CSV konnte nicht gelesen werden')}};r.readAsText(file,'utf-8')}
function renderVape(){
  const q=($('#vapeSearch')?.value||'').trim().toLowerCase();
  const allPs=S.vapeProducts.filter(p=>[p.name,p.variant,p.category,p.id,p.orderNo,p.ean].join(' ').toLowerCase().includes(q));
  const ps=q?allPs.slice(0,20):[];
  $('#vapeProductCount').textContent=S.vapeProducts.length;
  $('#vapeLeadCount').textContent=S.leads.length;
  $('#vapeQuoteCount').textContent=S.vapeQuotes.length;
  $('#vapeInvoiceCount').textContent=S.vapeInvoices.length;
  if($('#vapeMarkup'))$('#vapeMarkup').value=S.vapeMarkup;
  if($('#vapeMarkupValue'))$('#vapeMarkupValue').textContent=`${S.vapeMarkup}%`;
  const mapped=S.vapeProducts.filter(p=>privateEk(p)).length;
  if($('#vapeL3Status'))$('#vapeL3Status').textContent=Object.keys(S.vapePrivatePrices).length?`${Object.keys(S.vapePrivatePrices).length} L3-Werte geladen · ${mapped} Katalogartikel erkannt`:'Noch keine private L3-Datei geladen';
  const cart=cartItems(),cartNet=cart.reduce((a,x)=>a+x.qty*x.price,0);
  if($('#vapeCartBadge'))$('#vapeCartBadge').textContent=String(cartCount());
  if($('#vapeCart'))$('#vapeCart').innerHTML=cart.length?`<div class="row"><div><b>${cartCount()} Artikel</b><div class="meta">Warenwert netto ${money(cartNet)}</div></div><button class="secondary" data-cart-clear>🗑️ Leeren</button></div>${cart.map(x=>`<div class="row" style="padding:10px 0;border-bottom:1px solid var(--line)"><div><b>${esc(x.description)}</b><div class="meta">${esc(x.variant||'')} · ${money(x.price)} / Stück</div></div><div class="row compact"><button class="secondary" data-cart-minus="${esc(x.productId)}">−</button><b>${x.qty}</b><button class="secondary" data-cart-plus="${esc(x.productId)}">＋</button></div></div>`).join('')}<div class="row" style="margin-top:12px"><b>Netto</b><b>${money(cartNet)}</b></div>`:'<div class="empty">Warenkorb ist leer. Füge Produkte aus dem Katalog hinzu.</div>';
  let catalogHtml;
  if(!q){
    catalogHtml='<div class="empty">Gib oben einen Artikelnamen, eine EAN oder Bestellnummer ein, um Produkte anzuzeigen.</div>';
  }else if(!allPs.length){
    catalogHtml='<div class="empty">Keine Artikel gefunden.</div>';
  }else{
    catalogHtml=`<div class="meta" style="margin:0 0 10px">${allPs.length} Treffer · angezeigt werden maximal 20</div>`+ps.map(p=>{
      const ek=privateEk(p),vk=vapePrice(p);
      return `<article class="card"><div class="row"><div><h3>${esc(p.name)}</h3><div class="meta">${esc(p.variant||'')} · ${esc(p.category)} · ${esc(p.id)}</div></div><span class="badge">+ ${S.vapeMarkup}% EK</span></div><div class="chips"><span class="chip">RRP —</span>${ek!==null?`<span class="chip">EK L3 🔒 ${money(ek)}</span>`:'<span class="chip">EK L3 🔒 —</span>'}<span class="chip good">${vk===null?'VK —':`VK ${money(vk)}`}</span>${ek!==null?`<span class="chip">intern. Aufschlag ${S.vapeMarkup}%</span>`:'<span class="chip">L3-Zuordnung prüfen</span>'}</div><div class="lead-actions"><button ${vk===null?'disabled':''} data-vape-cart="${p.id}">🛒 In Warenkorb</button><button ${vk===null?'disabled':''} data-vape-add="${p.id}">＋ Einzel-Angebot</button></div></article>`;
    }).join('');
  }
  $('#vapeProductList').innerHTML=catalogHtml;
  $('#vapeQuoteList').innerHTML=S.vapeQuotes.map(q=>`<article class="card"><div class="row"><div><h3>${esc(q.number)} · ${esc(q.company)}</h3><div class="meta">${esc(q.date||'')} · ${esc(q.status||'Entwurf')}</div></div><b>${money(q.gross)}</b></div><div class="lead-actions"><button data-vq-edit="${q.id}">✏️ Bearbeiten</button><button data-vq-print="${q.id}">🖨️ Drucken / PDF</button><button data-vq-invoice="${q.id}">🧾 Rechnung</button></div></article>`).join('')||'<div class="empty">Noch keine Vape-Angebote.</div>';
  $('#vapeInvoiceList').innerHTML=S.vapeInvoices.map(i=>`<article class="card"><div class="row"><div><h3>${esc(i.number)} · ${esc(i.company)}</h3><div class="meta">${esc(i.date||'')} · fällig ${esc(i.due||'')}</div></div><b>${money(i.gross)}</b></div><div class="lead-actions"><button data-vi-edit="${i.id}">✏️ Bearbeiten</button><button data-vi-print="${i.id}">🖨️ Drucken / PDF</button></div></article>`).join('')||'<div class="empty">Noch keine Vape-Rechnungen.</div>';
}
$('#vapeSearch')?.addEventListener('input',renderVape);
function newVapeLine(container,item={}){const wrap=document.createElement('div');wrap.className='line-item vape-line';wrap.innerHTML=`<select class="vape-item-product">${vapeProductOptions()}</select><input class="vape-item-qty" type="number" min="0.01" step="1" value="${item.qty||1}"><input class="vape-item-price" type="number" min="0" step="0.01" value="${item.price??''}"><button type="button" class="icon-btn vape-remove">✕</button>`;container.appendChild(wrap);if(item.productId)wrap.querySelector('.vape-item-product').value=item.productId;const sel=wrap.querySelector('.vape-item-product'),price=wrap.querySelector('.vape-item-price');if(item.price==null&&item.productId){const p=S.vapeProducts.find(x=>x.id===item.productId);price.value=vapePrice(p)??''}sel.onchange=()=>{const p=S.vapeProducts.find(x=>x.id===sel.value);price.value=vapePrice(p)??''};wrap.querySelector('.vape-remove').onclick=()=>{wrap.remove();renderVapeTotals()};wrap.querySelectorAll('input').forEach(x=>x.oninput=renderVapeTotals);return wrap}
function getVapeItems(container){return [...container.querySelectorAll('.line-item')].map(r=>{const p=S.vapeProducts.find(x=>x.id===r.querySelector('.vape-item-product').value);return {productId:p?.id||'',description:p?.name||'',variant:p?.variant||'',qty:+r.querySelector('.vape-item-qty').value||0,unit:'Stück',price:+r.querySelector('.vape-item-price').value||0,ek:privateEk(p)}}).filter(x=>x.description&&x.qty>0&&x.price>0)}
function totals(items){const net=items.reduce((a,x)=>a+x.qty*x.price,0);return{net,vat:net*.19,gross:net*1.19}}
function renderVapeTotals(){const a=totals(getVapeItems($('#vapeQuoteItems'))),b=totals(getVapeItems($('#vapeInvoiceItems')));if($('#vqNetPreview')){$('#vqNetPreview').textContent=money(a.net);$('#vqVatPreview').textContent=money(a.vat);$('#vqGrossPreview').textContent=money(a.gross)}if($('#viNetPreview')){$('#viNetPreview').textContent=money(b.net);$('#viVatPreview').textContent=money(b.vat);$('#viGrossPreview').textContent=money(b.gross)}}
function fillLeadSelect(id){$('#'+id).innerHTML='<option value="">Ohne Lead</option>'+S.leads.map(l=>`<option value="${l.id}">${esc(l.company)}</option>`).join('')}
function customerOptions(selected=""){return '<option value="">Kunden auswählen …</option>'+S.customers.slice().sort((a,b)=>normalizeCompany(a.company).localeCompare(normalizeCompany(b.company))).map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${esc(c.company)}${c.contact?' · '+esc(c.contact):''}</option>`).join('')}
function fillVapeCustomer(selectId,companyId,contactId,emailId,vatId,customerNoId){const sel=$(selectId),c=customerById(sel?.value);if(c){$(companyId).value=c.company||'';$(contactId).value=c.contact||'';$(emailId).value=c.email||'';$(vatId).value=c.vatId||'';$(customerNoId).value=c.customerNo||''}}
function customerStats(c){const leads=S.leads.filter(x=>x.customerId===c.id),sumupQuotes=S.quotes.filter(x=>x.customerId===c.id),vapeQuotes=S.vapeQuotes.filter(x=>x.customerId===c.id),invoices=S.vapeInvoices.filter(x=>x.customerId===c.id),tasks=S.tasks.filter(x=>x.customerId===c.id||leads.some(l=>l.id===x.leadId)),visits=S.visits.filter(x=>x.customerId===c.id||leads.some(l=>l.id===x.leadId)),appointments=leads.filter(l=>l.status==='termin');return{leads,sumupQuotes,vapeQuotes,invoices,tasks,visits,appointments}}
function renderCustomers(){const q=($('#customerSearch')?.value||'').trim().toLowerCase();const a=S.customers.filter(c=>[c.company,c.contact,c.phone,c.email,c.address,c.customerNo,c.vatId].join(' ').toLowerCase().includes(q));$('#customerCount').textContent=S.customers.length;$('#customerList').innerHTML=a.map(c=>{const st=customerStats(c),sumup=st.leads.length>0||st.sumupQuotes.length>0,vape=st.vapeQuotes.length>0||st.invoices.length>0;return `<article class="card customer-card"><div class="row"><div><h3>${esc(c.company||'Ohne Firmenname')}</h3><div class="meta">${esc(c.contact||'Kein Ansprechpartner')}${c.phone?' · '+esc(c.phone):''}</div><div class="meta">${esc(c.email||'')}${c.customerNo?' · Kd.-Nr. '+esc(c.customerNo):''}</div></div><span class="badge">${st.vapeQuotes.length+st.sumupQuotes.length} Angebote · ${st.invoices.length} Rechnungen</span></div><div class="chips"><span class="chip ${sumup?'good':''}">🟠 SUMUP ${sumup?'aktiv':'—'}</span><span class="chip ${vape?'good':''}">🟣 VAPE ${vape?'aktiv':'—'}</span></div><div class="lead-actions"><button data-customer-view="${c.id}">👤 Kundenakte</button><button data-customer-edit="${c.id}">✏️ Bearbeiten</button><button data-customer-sumup="${c.id}">🟠 SUMUP-Angebot</button><button data-customer-vape="${c.id}">🛒 VAPE-Angebot</button></div></article>`}).join('')||'<div class="empty">Keine Kunden passend zur Suche.</div>'}
function customerTimeline(c,st){const events=[];for(const v of st.visits)events.push({date:v.date||v.createdAt?.slice(0,10)||'',icon:'📝',title:'Besuch',text:v.note||'Besuch dokumentiert',meta:'SUMUP / Außendienst',sort:v.createdAt||v.date||''});for(const l of st.leads)events.push({date:l.updatedAt?.slice(0,10)||l.due||'',icon:'🟠',title:'SUMUP · Lead',text:`${sl(l.status)} · TPV ${money(l.tpv)}`,meta:l.company||'',sort:l.updatedAt||''});for(const q of st.sumupQuotes)events.push({date:q.date||'',icon:'💼',title:'SUMUP · Angebot',text:`${q.number||''} · ${money(q.gross)}`,meta:q.status||'Entwurf',sort:q.date||''});for(const q of st.vapeQuotes)events.push({date:q.date||'',icon:'🟣',title:'VAPE · Angebot',text:`${q.number||''} · ${money(q.gross)}`,meta:q.status||'Entwurf',sort:q.date||''});for(const i of st.invoices)events.push({date:i.date||'',icon:'🧾',title:'VAPE · Rechnung',text:`${i.number||''} · ${money(i.gross)}`,meta:i.status||'Offen',sort:i.date||''});for(const t of st.tasks)events.push({date:t.due||'',icon:t.done?'☑️':'✅',title:t.done?'Aufgabe erledigt':'Wiedervorlage',text:t.title||'',meta:t.done?'Erledigt':'Offen',sort:t.due||''});return events.filter(e=>e.date||e.text).sort((a,b)=>(b.sort||b.date||'').localeCompare(a.sort||a.date||'')).slice(0,25)}
function openCustomer(id){const c=customerById(id);if(!c)return;const st=customerStats(c),lead=st.leads[0],timeline=customerTimeline(c,st);$('#customerDetailTitle').textContent=c.company||'Kundenakte';$('#customerDetailBody').innerHTML=`<div class="customer-detail-head"><div><h3>${esc(c.company||'')}</h3><div class="meta">Kundennr. ${esc(c.customerNo||'—')}</div></div></div><div class="customer-actions"><button class="primary" data-customer-task="${c.id}">✅ Aufgabe</button><button class="secondary" data-customer-sumup="${c.id}">🟠 SUMUP</button><button class="secondary" data-customer-vape="${c.id}">🟣 VAPE</button><button class="secondary" data-customer-invoice="${c.id}">🧾 Rechnung</button></div><div class="detail-grid"><div><b>Ansprechpartner</b><span>${esc(c.contact||'—')}</span></div><div><b>Telefon</b><span>${c.phone?`<a href="tel:${esc(c.phone)}">${esc(c.phone)}</a>`:'—'}</span></div><div><b>E-Mail</b><span>${c.email?`<a href="mailto:${esc(c.email)}">${esc(c.email)}</a>`:'—'}</span></div><div><b>USt-IdNr.</b><span>${esc(c.vatId||'—')}</span></div><div class="full"><b>Adresse</b><span>${esc(c.address||'—')}</span></div><div class="full"><b>Notizen</b><span>${esc(c.notes||'—')}</span></div></div><div class="section-title"><h3>Aktivität</h3></div><div class="kpi-grid"><div class="kpi"><span>SUMUP Leads</span><b>${st.leads.length}</b></div><div class="kpi"><span>Besuche</span><b>${st.visits.length}</b></div><div class="kpi"><span>Offene Aufgaben</span><b>${st.tasks.filter(t=>!t.done).length}</b></div><div class="kpi"><span>Termine</span><b>${st.appointments.length}</b></div><div class="kpi"><span>VAPE Angebote</span><b>${st.vapeQuotes.length}</b></div><div class="kpi"><span>VAPE Rechnungen</span><b>${st.invoices.length}</b></div></div><div class="section-title"><h3>Aktivitäts-Timeline</h3></div><div class="timeline">${timeline.map(e=>`<div class="timeline-item"><div class="timeline-icon">${e.icon}</div><div><b>${esc(e.title)}</b><div class="meta">${esc(fmtDate(e.date))}${e.meta?' · '+esc(e.meta):''}</div><div>${esc(e.text)}</div></div></div>`).join('')||'<div class="empty">Noch keine Aktivitäten.</div>'}</div><div class="section-title"><h3>SUMUP</h3></div><div class="detail-list">${lead?`<div class="card"><b>🟠 ${esc(lead.company)}</b><div class="meta">${esc(sl(lead.status))} · TPV ${money(lead.tpv)}${lead.due?' · nächster Kontakt '+esc(fmtDate(lead.due)):''}</div><div class="lead-actions"><button class="secondary" data-detail-lead="${lead.id}">Lead öffnen</button><button class="secondary" data-detail-visit="${lead.id}">📝 Besuch</button></div></div>`:'<div class="empty">Noch kein SUMUP-Lead.</div>'}</div><div class="section-title"><h3>Dokumente</h3></div><div class="detail-list">${st.sumupQuotes.map(q=>`<div class="card"><b>💼 ${esc(q.number)}</b><div class="meta">SUMUP-Angebot · ${esc(q.date||'')} · ${money(q.gross)}</div></div>`).join('')}${st.vapeQuotes.map(q=>`<div class="card"><b>🟣 ${esc(q.number)}</b><div class="meta">VAPE-Angebot · ${esc(q.date||'')} · ${money(q.gross)}</div></div>`).join('')}${st.invoices.map(i=>`<div class="card"><b>🧾 ${esc(i.number)}</b><div class="meta">VAPE-Rechnung · ${esc(i.date||'')} · ${money(i.gross)}</div></div>`).join('')||'<div class="empty">Noch keine Dokumente.</div>'}</div>`;$('#customerDetailBody').dataset.customerId=id;open('customerDetailDialog')}
function editCustomer(id){const c=customerById(id);if(!c)return;$('#customerForm').reset();$('#customerId').value=c.id;$('#customerFormTitle').textContent='Kunde bearbeiten';for(const [k,i] of Object.entries({company:'cCompany',customerNo:'cCustomerNo',contact:'cContact',phone:'cPhone',email:'cEmail',street:'cStreet',zip:'cZip',city:'cCity',territory:'cTerritory',priority:'cPriority',vatId:'cVatId',notes:'cNotes'}))$('#'+i).value=c[k]||'';open('customerDialog')}
