$('#customerForm')?.addEventListener('submit',e=>{e.preventDefault();const company=$('#cCompany').value.trim();if(!company)return toast('Firma / Kunde fehlt');let c=customerById($('#customerId').value)||findMatchingCustomer({company,email:$('#cEmail').value.trim()});if(!c)c={id:uid(),customerNo:$('#cCustomerNo').value.trim()||nextCustomerNo(),company};syncCustomer(c,{company,customerNo:$('#cCustomerNo').value.trim(),contact:$('#cContact').value.trim(),phone:$('#cPhone').value.trim(),email:$('#cEmail').value.trim(),street:$('#cStreet').value.trim(),zip:$('#cZip').value.trim(),city:$('#cCity').value.trim(),address:addressText($('#cStreet').value.trim(),$('#cZip').value.trim(),$('#cCity').value.trim()),territory:$('#cTerritory').value.trim(),priority:$('#cPriority').value,vatId:$('#cVatId').value.trim(),notes:$('#cNotes').value.trim()});if(!S.customers.some(x=>x.id===c.id))S.customers.unshift(c);save();close('customerDialog');renderCustomers();toast('Kunde gespeichert')});
function newVapeQuote(productId=null,leadId=null,existing=null,cart=null){$('#vapeQuoteForm').reset();$('#vqId').value=existing?.id||'';fillLeadSelect('vqLead');const existingCustomerId=existing?.customerId||S.leads.find(l=>l.id===(existing?.leadId||leadId))?.customerId||'';$('#vqCustomer').innerHTML=customerOptions(existingCustomerId);$('#vqCustomer').value=existingCustomerId;$('#vqDate').value=existing?.date||today();$('#vqCompany').value=existing?.company||'';$('#vqCustomerNo').value=existing?.customerNo||'';$('#vqContact').value=existing?.contact||'';$('#vqEmail').value=existing?.email||'';$('#vqVatId').value=existing?.vatId||'';$('#vqNote').value=existing?.note||'';$('#vapeQuoteItems').innerHTML='';(existing?.items||cart||[]).forEach(i=>newVapeLine($('#vapeQuoteItems'),i));if(!existing?.items?.length&&!cart?.length)newVapeLine($('#vapeQuoteItems'),productId?{productId,qty:1,price:vapePrice(S.vapeProducts.find(p=>p.id===productId))}:{});if(leadId){$('#vqLead').value=leadId;$('#vqLead').dispatchEvent(new Event('change'))}if(existing)$('#vqLead').value=existing.leadId||'';renderVapeTotals();open('vapeQuoteDialog')}
